/// TC010 (US0002 AC1): VAD compares rms against the 0.005 threshold.
/// (Exact-equality strictness `>` vs `>=` is not observable at f32 precision —
/// 0.005 is not exactly representable — so we assert the boundary direction.)
#[test]
fn tc010_vad_threshold_direction() {
    let mut vad = Vad::new();
    // A constant-amplitude buffer has rms == |value|.
    let below = vec![0.004f32; Vad::CHUNK_SIZE];
    let above = vec![0.006f32; Vad::CHUNK_SIZE];
    assert!(!vad.process_chunk(&below), "rms below threshold is silence");
    assert!(vad.process_chunk(&above), "rms above threshold is speech");
}

/// TC011 (US0002): VAD segmentation constants match the spec.
#[test]
fn tc011_vad_constants_match_spec() {
    assert_eq!(Vad::CHUNK_SIZE, 1_600);
    assert_eq!(Vad::MIN_START_CHUNKS, 3);
    assert_eq!(Vad::SILENCE_END_CHUNKS, 8);
    assert_eq!(Vad::MIN_SPEECH_SAMPLES, 8_000);
    assert_eq!(Vad::FLUSH_SAMPLES, 48_000);
}

/// TC422 (US0024 AC3): merge averages mic+sys and zero-pads the shorter channel.
#[test]
fn tc422_recorder_merge_averages_and_zero_pads() {
    let dir = tempfile::tempdir().unwrap();
    let spec = hound::WavSpec {
        channels: 1,
        sample_rate: 16_000,
        bits_per_sample: 32,
        sample_format: hound::SampleFormat::Float,
    };
    let mic = dir.path().join("mic.wav");
    let sys = dir.path().join("sys.wav");
    let out = dir.path().join("merged.wav");

    {
        let mut w = hound::WavWriter::create(&mic, spec).unwrap();
        for s in [0.4f32, 0.4] {
            w.write_sample(s).unwrap();
        }
        w.finalize().unwrap();
    }
    {
        // sys is shorter → second sample must be zero-padded on merge.
        let mut w = hound::WavWriter::create(&sys, spec).unwrap();
        w.write_sample(0.2f32).unwrap();
        w.finalize().unwrap();
    }

    AudioRecorder::merge(&mic, &sys, &out).unwrap();

    let mut reader = hound::WavReader::open(&out).unwrap();
    let samples: Vec<f32> = reader.samples::<f32>().map(|s| s.unwrap()).collect();
    assert_eq!(samples.len(), 2, "merge length is max(mic, sys)");
    assert!((samples[0] - 0.3).abs() < 1e-4, "(0.4+0.2)/2 == 0.3");
    assert!((samples[1] - 0.2).abs() < 1e-4, "(0.4+0.0)/2 == 0.2 (sys padded)");
}

