/// TC224 (US0016 AC5): cosine similarity known fractional value.
#[test]
fn tc224_cosine_known_value() {
    let a = [1.0f32, 0.0];
    let b = [1.0f32, 1.0];
    let sim = cosine_similarity(&a, &b);
    // 1 / sqrt(2) ≈ 0.70710678
    assert!((sim - std::f32::consts::FRAC_1_SQRT_2).abs() < 1e-5, "got {sim}");
}

