/// TC304 (US0019 AC4): language instruction only for non-English, non-auto locales.
#[test]
fn tc304_language_instruction_rules() {
    for empty in ["", "  ", "auto", "en", "en-US", "EN", "  en  "] {
        assert!(
            language_response_instruction(empty).is_empty(),
            "{empty:?} should produce no instruction"
        );
    }
    for foreign in ["es", "fr", "  es  ", "de-DE", "ja"] {
        assert!(
            language_response_instruction(foreign)
                .contains("Write your entire response in the same language"),
            "{foreign:?} should append the language instruction"
        );
    }
}

/// TC302/TC304 (US0019): build_notes_messages yields [system, user] and appends
/// the language instruction to the user message only for foreign locales.
#[test]
fn tc302_build_notes_messages_shape_and_language() {
    let template = &MeetingTemplate::built_ins()[0]; // Summary
    let records = vec![SessionRecord {
        speaker: Speaker::You,
        participant_id: None,
        participant_label: None,
        text: "let me summarise the pricing tiers".into(),
        timestamp: Utc::now(),
        suggestions: None,
        kb_hits: None,
        suggestion_decision: None,
        surfaced_suggestion_text: None,
        conversation_state_summary: None,
    }];

    let en = build_notes_messages(&records, template, "en");
    assert_eq!(en.len(), 2);
    assert_eq!(en[0].role, "system");
    assert_eq!(en[0].content, template.system_prompt);
    assert_eq!(en[1].role, "user");
    assert!(en[1].content.contains("let me summarise the pricing tiers"));
    assert!(!en[1]
        .content
        .contains("Write your entire response in the same language"));

    let es = build_notes_messages(&records, template, "es");
    assert!(es[1]
        .content
        .contains("Write your entire response in the same language"));
}

/// TC310 (US0020 AC1): exactly 6 built-in templates with stable UUIDs/icons.
#[test]
fn tc310_builtin_templates() {
    let builtins = MeetingTemplate::built_ins();
    assert_eq!(builtins.len(), 6);
    assert!(builtins.iter().all(|t| t.is_built_in));

    let summary = builtins
        .iter()
        .find(|t| t.id.to_string() == "00000000-0000-0000-0000-000000000000")
        .expect("Summary template present");
    assert_eq!(summary.name, "Summary");
    assert_eq!(summary.icon, "doc.text");

    assert!(builtins
        .iter()
        .any(|t| t.id.to_string() == "00000000-0000-0000-0000-000000000005"));
}

