/// TC320 (US0021 AC1): normalize_relative_folder drops empty/./.. segments and
/// handles both `/` and `\` separators.
#[test]
fn tc320_normalize_relative_folder() {
    assert_eq!(normalize_relative_folder("a/b"), PathBuf::from("a").join("b"));
    assert_eq!(normalize_relative_folder("a//b/"), PathBuf::from("a").join("b"));
    assert_eq!(
        normalize_relative_folder("./a/../b"),
        PathBuf::from("a").join("b")
    );
    assert_eq!(normalize_relative_folder("a\\b"), PathBuf::from("a").join("b"));
    assert_eq!(normalize_relative_folder(""), PathBuf::new());
    assert_eq!(normalize_relative_folder("  "), PathBuf::new());
}
